mapper.update:
UPDATE extension_connect_session
SET status = 'AUTHORIZED',
    user_id = #{userId},
    authorized_at = #{authorizedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE extension_connect_session
SET status = 'DENIED'
WHERE id = #{id}
  AND status = #{expectedStatus}

UPDATE extension_connect_session
SET status = 'EXCHANGED',
    exchanged_at = #{exchangedAt}
WHERE id = #{id}
  AND status = #{expectedStatus}
